<script>
const q=document.getElementById('serie_busqueda'), results=document.getElementById('serie_resultados'), selected=document.getElementById('serie_seleccionadas'), chosen=new Map();
function drawSelected(){selected.innerHTML='';chosen.forEach((x,id)=>{const chip=document.createElement('span');chip.className='ge-chip';chip.innerHTML=`${x.serie}<button type="button" aria-label="Quitar">×</button><input type="hidden" name="serial_ids[]" value="${id}">`;chip.querySelector('button').onclick=()=>{chosen.delete(id);drawSelected()};selected.appendChild(chip)})}
let timer; q.addEventListener('input',()=>{clearTimeout(timer);const term=q.value.trim();if(term.length<2){results.innerHTML='';return}timer=setTimeout(async()=>{const r=await fetch(`{{ route('admin.guia_entregas.search_seriales') }}?q=${encodeURIComponent(term)}`,{headers:{Accept:'application/json'}});const data=await r.json();results.innerHTML='';data.forEach(x=>{const b=document.createElement('button');b.type='button';b.className='ge-result';b.textContent=`${x.serie} · ${x.equipo||x.codigo||'Equipo'}`;b.onclick=()=>{chosen.set(String(x.id),x);drawSelected();results.innerHTML='';q.value=''};results.appendChild(b)})},250)});
const canvas=document.getElementById('firma'),ctx=canvas.getContext('2d');function resize(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;ctx.scale(d,d);ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#2563eb'}resize();addEventListener('resize',resize);let drawing=false,last;function point(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}canvas.onpointerdown=e=>{drawing=true;last=point(e);canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drawing)return;const p=point(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;document.getElementById('limpiarFirma').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height)};document.querySelector('form').addEventListener('submit',()=>{document.getElementById('firmaData').value=canvas.toDataURL('image/png')});
</script>
